begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
select ok(not has_table_privilege(r,t,op) and not has_any_column_privilege(r,t,op),t||': '||r||' has no '||op)
from unnest(array['public.program_media','public.program_tags','public.program_tag_links','public.program_gallery']) t
cross join unnest(array['anon','service_role']) r cross join unnest(array['SELECT','INSERT','UPDATE']) op;
select ok(not has_table_privilege(r,t,'DELETE'),t||': '||r||' has no DELETE')
from unnest(array['public.program_media','public.program_tags','public.program_tag_links','public.program_gallery']) t cross join unnest(array['anon','service_role']) r;
select ok(not has_table_privilege('authenticated',t,op) and not has_any_column_privilege('authenticated',t,op),t||': no authenticated definition '||op)
from unnest(array['public.program_media','public.program_tags']) t cross join unnest(array['INSERT','UPDATE']) op;
create function pg_temp.affected(statement text) returns bigint language plpgsql security invoker as $$declare n bigint;begin execute statement;get diagnostics n=row_count;return n;end $$;
create temporary table seed_before as select id,definition,catalog_metadata from program_versions where owner_id='6ab9fb82-8aae-5e49-9f9d-535b4a25d302';
select ok(not exists(select 1 from program_versions v cross join lateral jsonb_array_elements_text(v.catalog_metadata->'equipmentIds') e join equipment_types t on t.id=e.value::uuid where t.slug='none'),'None is not a required piece of guidance equipment');
select is((select count(*)::int from seed_before),14,'exactly fourteen original immutable definitions');
select is((select count(*)::int from auth.users where id='6ab9fb82-8aae-5e49-9f9d-535b4a25d302'),0,'Body platform principal has no fabricated login');
select ok((select principal_kind='platform' and auth_user_id is null from profiles where id='6ab9fb82-8aae-5e49-9f9d-535b4a25d302'),'restricted platform identity, not an end-user profile');
select throws_ok($$insert into profiles(id,display_name) values(gen_random_uuid(),'Not an auth user')$$,'23503',null,'person profiles still require a real auth identity');
select is((select count(*)::int from workout_sessions where owner_id='6ab9fb82-8aae-5e49-9f9d-535b4a25d302'),0,'seeding never creates actual workouts');
select lives_ok('select body_private.install_body_catalog()','catalog replay is idempotent');
select lives_ok('select body_private.install_body_catalog()','second replay is idempotent');
select ok(not exists(select 1 from seed_before b join program_versions v using(id) where b.definition<>v.definition or b.catalog_metadata<>v.catalog_metadata),'replays never rewrite immutable recipes');
select ok(not exists(select 1 from programs p where p.origin='body_authored' and (p.owner_id<>p.publisher_id or p.publication_status<>'published' or not p.recommendation_eligible or p.first_published_at is null)),'official ownership and publication authority');
select ok(not exists(select 1 from programs p where p.origin='body_authored' and (select count(*) from program_days d where d.program_id=p.id)<>p.cycle_length),'all cycle positions present');
select ok(exists(select 1 from programs where cycle_length=8 and origin='body_authored') and exists(select 1 from programs where cycle_length=9 and origin='body_authored'),'nonweekly eight- and nine-day rotations');
select ok(not exists(select 1 from program_days d where d.owner_id='6ab9fb82-8aae-5e49-9f9d-535b4a25d302' and (d.is_rest_day=exists(select 1 from program_slots s where s.program_day_id=d.id))),'every training day has slots and every rest day is empty');
select ok(not exists(select 1 from program_slots s where s.owner_id='6ab9fb82-8aae-5e49-9f9d-535b4a25d302' and s.target_sets<>(select count(*) from program_set_prescriptions x where x.slot_id=s.id)),'every slot has the prescribed number of ordered working sets');
select ok(not exists(select 1 from program_set_prescriptions where owner_id='6ab9fb82-8aae-5e49-9f9d-535b4a25d302' and (not public.valid_effort(effort_scale,effort_value) or reps_min<1 or reps_max<reps_min or set_type<>'working')),'valid rep and effort prescriptions, without fake actuals');
select ok(not exists(select 1 from program_set_prescriptions x join program_slots s on s.id=x.slot_id join program_days d on d.id=s.program_day_id join programs p on p.id=d.program_id where p.experience_level='beginner' and p.origin='body_authored' and x.intended_to_failure),'no beginner failure prescriptions');
select ok(not exists(select 1 from program_set_prescriptions x join program_slots s on s.id=x.slot_id join exercises e on e.id=s.exercise_id where x.owner_id='6ab9fb82-8aae-5e49-9f9d-535b4a25d302' and x.intended_to_failure and (e.exercise_type<>'isolation' or x.position<>s.target_sets)),'failure intent limited to final isolation sets');
select set_config('request.jwt.claims','{"sub":"6ab9fb82-8aae-5e49-9f9d-535b4a25d302","role":"authenticated"}',true);
select ok(not exists(select 1 from program_slots s where s.owner_id=auth.uid() and not program_slot_eligible(s.id,s.exercise_id)),'every default meets taxonomy and equipment constraints');
select ok(not exists(select 1 from program_slot_alternatives a where a.owner_id=auth.uid() and not program_slot_eligible(a.slot_id,a.exercise_id)),'every alternative meets the same hard constraints');
select ok(not exists(select 1 from program_equipment q join programs p on p.id=q.program_id join equipment_types e on e.id=q.equipment_type_id where p.slug='dumbbell-only-full-body' and e.slug not in('dumbbell','none')),'dumbbell plan has no hidden station/bench requirements');
select ok(not exists(select 1 from program_versions where owner_id=auth.uid() and (length(definition->'program'->>'description_markdown')<500 or jsonb_array_length(definition->'days')<3 or jsonb_array_length(definition->'rules')<3)),'all definitions include original guidance, complete workouts and progression');
insert into auth.users(id) values(md5('library_a')::uuid),(md5('library_b')::uuid);
insert into profiles(id,display_name) values(md5('library_a')::uuid,'A'),(md5('library_b')::uuid,'B');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('library_a')::uuid,'role','authenticated')::text,true);
select is((program_catalog()->>'total')::int,14,'authenticated catalog exposes exactly fourteen approved templates');
select is(jsonb_array_length(program_catalog()->'items'),6,'card results are paginated');
select is(jsonb_array_length(program_catalog(p_page=>2)->'items'),6,'second page preserves all twelve');
select ok(not exists(select 1 from jsonb_array_elements(program_catalog()->'items') x where x ? 'definition' or x ? 'days'),'cards do not download full recipes');
select is((program_catalog(p_query=>'Dumbbell')->>'total')::int,1,'server-side title search');
select is((program_catalog(p_goal=>'strength_size',p_split=>'full_body',p_experience=>'beginner',p_equipment=>'dumbbells',p_frequency=>'2_3')->>'total')::int,1,'combined goal/split/experience/equipment/frequency filters');
select is((program_catalog(p_style=>'low_volume')->>'total')::int,1,'controlled style filtering');
select throws_ok($$select program_catalog(p_page=>0)$$,'22023',null,'invalid pagination denied');
select throws_ok($$select program_catalog(p_goal=>'made_up')$$,'22023',null,'invalid facets denied');
select throws_ok($$select program_catalog(p_goal=>null)$$,'22023',null,'null facets denied');
select is((select count(*)::int from program_versions where owner_id='6ab9fb82-8aae-5e49-9f9d-535b4a25d302'),14,'only approved immutable versions readable');
select is((select count(*)::int from program_days where owner_id='6ab9fb82-8aae-5e49-9f9d-535b4a25d302'),0,'mutable official draft children remain hidden');
select is(pg_temp.affected($$update programs set summary='Tampered' where origin='body_authored'$$),0::bigint,'ordinary user cannot edit official summaries');
select is(pg_temp.affected($$delete from program_tag_links where owner_id='6ab9fb82-8aae-5e49-9f9d-535b4a25d302'$$),0::bigint,'ordinary user cannot alter official tags');
select throws_ok($$update programs set first_published_at=now(),featured=true where origin='body_authored'$$,'42501',null,'publication age and badges cannot be forged');
select throws_ok($$update program_versions set catalog_metadata='{}'$$,'42501',null,'catalog projections cannot be forged');
select throws_ok($$update program_media set approved=true$$,'42501',null,'controlled media is not creator writable');
select throws_ok($$insert into profiles(id,display_name,principal_kind) values(auth.uid(),'Body','platform')$$,'42501',null,'ordinary account cannot claim platform principal');
select throws_ok($$select body_private.install_body_catalog()$$,'42501',null,'seed installer not a client endpoint');
select set_config('body_test.copy',clone_program((select published_version_id from programs where slug='dumbbell-only-full-body'),'My private copy',md5('library_clone')::uuid)::text,true);
select ok((select owner_id=auth.uid() and origin='user_copy' and visibility='private' and publication_status='unpublished' and summary is not null from programs where id=current_setting('body_test.copy')::uuid),'approved official template clones into an independent private instance');
select is((select count(*)::int from program_tag_links where program_id=current_setting('body_test.copy')::uuid),4,'copy retains descriptive tags');
insert into program_gallery(program_id,owner_id,position,media_id) select current_setting('body_test.copy')::uuid,auth.uid(),1,id from program_media limit 1;
select set_config('body_test.gallery_version',snapshot_program(current_setting('body_test.copy')::uuid)::text,true);
select set_config('body_test.gallery_copy',clone_program(current_setting('body_test.gallery_version')::uuid,'Gallery copy',md5('gallery_clone')::uuid)::text,true);
select is((select count(*)::int from program_gallery where program_id=current_setting('body_test.gallery_copy')::uuid),1,'immutable gallery references clone into the independently owned copy');
insert into programs(id,owner_id,name,cycle_length,visibility) values(md5('library_private')::uuid,auth.uid(),'Not a public plan',3,'public');
select set_config('request.jwt.claims',json_build_object('sub',md5('library_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from programs where id in(md5('library_private')::uuid,current_setting('body_test.copy')::uuid)),0,'private intent and cloned programs remain cross-owner hidden');
select is((select count(*)::int from program_tag_links where program_id=current_setting('body_test.copy')::uuid),0,'copied tags remain owner-private');
select throws_ok($$insert into program_gallery(program_id,owner_id,position,media_id) select current_setting('body_test.copy')::uuid,auth.uid(),1,id from program_media limit 1$$,'42501',null,'cross-owner gallery insertion denied');
select is((program_catalog()->>'total')::int,14,'private programs never join official results');
reset role;
select throws_ok($$update programs set first_published_at=now() where id=md5('library_private')::uuid$$,'23514',null,'private draft creation cannot establish publication age');
create temporary table publication_before as select id,first_published_at,published_version_id from programs where slug='full-body-foundation';
update programs set publication_status='withdrawn' where id=(select id from publication_before);
grant select on publication_before to authenticated;
set local role authenticated;
select is((select count(*)::int from programs where id=(select id from publication_before)),0,'withdrawn root is not readable');
select is((select count(*)::int from program_versions where id=(select published_version_id from publication_before)),0,'withdrawn immutable source is not readable');
select is((program_catalog()->>'total')::int,13,'withdrawn plans disappear from discovery');
reset role;
update programs set publication_status='published' where id=(select id from publication_before);
select ok((select p.first_published_at=b.first_published_at from programs p join publication_before b using(id)),'republishing does not reset New age');
select throws_ok($$update programs set first_published_at=now() where id=(select id from publication_before)$$,'23514',null,'initial authorized publication time is immutable');
-- Administrative draft edits do not rewrite the published source or card.
update programs set summary='Unpublished draft change' where id=(select id from publication_before);
select ok((select v.catalog_metadata->>'summary'<>'Unpublished draft change' and v.definition->'program'->>'summary'<>'Unpublished draft change' from program_versions v join publication_before b on b.published_version_id=v.id),'browse and detail content both remain immutable');
set local role anon;
select throws_ok('select program_catalog()','42501',null,'anonymous catalog RPC denied');
select throws_ok('select * from program_versions','42501',null,'anonymous template reads denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select is((select count(*)::int from programs),0,'authenticated role without verified UID cannot read catalog roots');
select is((select count(*)::int from program_versions),0,'authenticated role without verified UID cannot read official versions');
select is((select count(*)::int from program_media),0,'authenticated role without verified UID cannot read media metadata');
select throws_ok('select program_catalog()','42501',null,'missing identity fails closed in catalog RPC');
reset role;
select * from finish();rollback;
